const src="ts/ts_0001/structures/candidate_7bd447631ec64b94e92a.xyz";
for (const [tag,deg] of [["A",120],["B",-120]]) {
  const t = await tools.internal_coordinates({mode:"transform", input_path:src, charge:-1,
    operations:[{type:"rotate", axis_atoms:[2,3], side_of_bond:[2,3], degrees:deg},
                {type:"stretch", atoms:[3,4], new_length:2.35}],
    output_path:`ts/ts_0001/guess_${tag}.xyz`});
  text(tag+": "+(t.data.report? t.data.report.slice(0,600):t.summary));
}
const a = await tools.internal_coordinates({input_path:"ts/ts_0001/guess_A.xyz", charge:-1, reactive_atoms:[1,2,3,4,7], watch_pairs:[[1,7],[2,7],[3,4],[2,3]]});
text("A report:\n"+a.data.report.slice(0,1200));

const b = await tools.bash({command:`python3 - <<'EOF'
import numpy as np, itertools, math
def xyz(p):
    L=open(p).read().split('\\n')
    n=int(L[0]); at=[]
    for l in L[2:2+n]:
        s=l.split(); at.append((s[0],np.array(list(map(float,s[1:4])))))
    return at
def dih(a,b,c,d):
    b0=-(b-a); b1=c-b; b2=d-c; b1/=np.linalg.norm(b1)
    v=b0-np.dot(b0,b1)*b1; w=b2-np.dot(b2,b1)*b1
    return math.degrees(math.atan2(np.dot(np.cross(b1,v),w),np.dot(v,w)))
for tag in "AB":
    at=xyz(f"ts/ts_0001/guess_{tag}.xyz")
    print(tag, "H7-C2-C3-Cl4 =", round(abs(dih(at[6][1],at[1][1],at[2][1],at[3][1])),1),
          " H5-C2-C3-Cl4 =", round(abs(dih(at[4][1],at[1][1],at[2][1],at[3][1])),1),
          " C3-Cl4/H7 dist", round(np.linalg.norm(at[3][1]-at[6][1]),2))
EOF`});
text(b.data.result);

